static inline void CPU_INT(int n, int cycles)
{
    cpuRegs.interrupt |= 1u << n;
    cpuRegs.eCycle[n] = static_cast<u32>(cycles);
}
#define IPU_INT_TO(cycles) if (!(cpuRegs.interrupt & (1 << DMAC_TO_IPU))) CPU_INT(DMAC_TO_IPU, cycles)
#define IPU_INT_FROM(cycles) CPU_INT(DMAC_FROM_IPU, cycles)
#define IPU_INT_PROCESS(cycles) if (!(cpuRegs.interrupt & (1 << IPU_PROCESS))) CPU_INT(IPU_PROCESS, cycles)
