static bool hwDmacSrcChain(DMACh &dma, int id)
{
    u32 temp;
    switch (id)
    {
    case TAG_REFE:
        dma.tadr += 16;
        return true;
    case TAG_CNT:
        dma.madr = dma.tadr + 16;
        dma.tadr = dma.madr;
        return false;
    case TAG_NEXT:
        temp = dma.madr;
        dma.madr = dma.tadr + 16;
        dma.tadr = temp;
        return false;
    case TAG_REF:
    case TAG_REFS:
        dma.tadr += 16;
        return false;
    case TAG_CALL:
        temp = dma.madr;
        dma.madr = dma.tadr + 16;
        if (dma.chcr.ASP == 0) dma.asr0 = dma.madr + (dma.qwc << 4);
        else if (dma.chcr.ASP == 1) dma.asr1 = dma.madr + (dma.qwc << 4);
        else return true;
        dma.chcr.ASP++;
        dma.tadr = temp;
        return false;
    case TAG_RET:
        dma.madr = dma.tadr + 16;
        if (dma.chcr.ASP == 2) { dma.tadr = dma.asr1; dma.asr1 = 0; dma.chcr.ASP = 1; }
        else if (dma.chcr.ASP == 1) { dma.tadr = dma.asr0; dma.asr0 = 0; dma.chcr.ASP = 0; }
        else return true;
        return false;
    case TAG_END:
        dma.madr = dma.tadr + 16;
        return true;
    }
    return false;
}
static inline void hwDmacSrcTadrInc(DMACh &dma)
{
    if (dma.chcr.STR == 0 || dma.chcr.MOD != CHAIN_MODE)
        return;
    if (((dma.chcr.TAG >> 12) & 7) == TAG_CNT)
        dma.tadr = dma.madr;
}

